-- submissions/reject-crash
-- A rejected new report's draft crash is marked rejected; it stays in the database for the record.
--
-- Parameters, with the example values used to render this file:
--   $1 = "rejected"
--   $2 = "0199c8a0-0000-7000-8000-00000000000a"
--   $3 = "draft"
--   $4 = "pending"
--
-- Generated by `pnpm db:queries` from lib/db/queries/submissions.ts. Do not edit by hand.

update "crashes"
set "status" = $1, "version" = "crashes"."version" + 1, "updated_at" = now()
where ("crashes"."id" = $2
  and "crashes"."status" in ($3, $4))
returning "id", "slug", "status", "merged_into_id", "title_en", "title_np", "occurred_on", "occurred_time", "location", "location_precision", "place_name_en", "place_name_np", "province_id", "district_id", "local_unit_id", "deaths", "injured_total", "created_via", "verification_level", "version", "created_at", "updated_at";
